validator:
function validate(input) {
  const [{ Products = [], Purchases = [] }] = input;
  const products = new Set(), lines = new Set();
  for (const [id, price] of Products) {
    if (id === null || price === null) return 'product_id and price are required.';
    if (products.has(id)) return `product_id ${id} appears twice in Products.`;
    products.add(id);
    if (price <= 0) return 'price must be positive.';
  }
  for (const [invoice, product, quantity] of Purchases) {
    if (invoice === null || product === null || quantity === null) return 'Purchases values are required.';
    if (!products.has(product)) return `Purchases names product ${product}, which is not in Products.`;
    const key = `${invoice}|${product}`;
    if (lines.has(key)) return `Invoice ${invoice} lists product ${product} twice.`;
    lines.add(key);
    if (quantity <= 0) return 'quantity must be positive.';
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const Products = [], Purchases = [];
  if (size === 'small') {
    // Round prices and small quantities make equal invoice totals common.
    const prices = [50, 100, 100, 200, 300];
    for (let id = 1; id <= 4; id++) if (rand() < 0.75) Products.push([id, prices[pick(prices.length)]]);
    const quantities = [1, 1, 2, 2, 3, 4, 10];
    const seen = new Set(), rows = pick(9);
    for (let tries = 0; Products.length && Purchases.length < rows && tries < 40; tries++) {
      const invoice = 1 + pick(5), product = Products[pick(Products.length)][0];
      if (seen.has(`${invoice}|${product}`)) continue;
      seen.add(`${invoice}|${product}`);
      Purchases.push([invoice, product, quantities[pick(quantities.length)]]);
    }
  } else {
    for (let id = 1; id <= 400; id++) Products.push([id, 1 + pick(50)]);
    const seen = new Set();
    while (Purchases.length < 2000) {
      const invoice = 1 + pick(500), product = 1 + pick(400);
      if (seen.has(`${invoice}|${product}`)) continue;
      seen.add(`${invoice}|${product}`);
      Purchases.push([invoice, product, 1 + pick(20)]);
    }
  }
  return [{ Products, Purchases }];
}
